parameters.functionCode:
const items = $input.all();
const currentDate = $('Set Variables').item.json.current_date;
const partner = $('Set Variables').item.json.partner;
const reportType = $('Set Variables').item.json.report_type;

const expectedPattern = new RegExp(`^${partner}_${reportType}_${currentDate}\\.csv$`);

const validFiles = items.filter(item => {
  const filename = item.json.name;
  const fileAge = (Date.now() - new Date(item.json.modifyTime)) / (1000 * 60 * 60);
  return expectedPattern.test(filename) && item.json.size > 0 && fileAge <= 24;
});

if (validFiles.length > 0) {
  const file = validFiles[0].json;
  return [{
    json: {
      file_found: true,
      filename: file.name,
      size: file.size,
      size_mb: (file.size / 1024 / 1024).toFixed(2),
      modified_time: new Date(file.modifyTime).toISOString(),
      actual_time: new Date(file.modifyTime).toLocaleTimeString('en-IN', { timeZone: 'Asia/Kolkata' }),
      report_type: reportType,
      partner: partner,
      validation: 'Valid',
      status: '✅ On Time'
    }
  }];
} else {
  return [{
    json: {
      file_found: false,
      filename: `${partner}_${reportType}_${currentDate}.csv`,
      size: 0,
      size_mb: '0',
      modified_time: null,
      actual_time: '-',
      report_type: reportType,
      partner: partner,
      validation: 'Missing',
      status: '❌ Missing'
    }
  }];
}

