const item = $input.first();
const expectedTime = $('Set Variables').item.json.expected_time;
const currentDate = $('Set Variables').item.json.current_date;

return [{
  json: {
    date: `${currentDate.slice(0,4)}-${currentDate.slice(4,6)}-${currentDate.slice(6,8)}`,
    partner: item.json.partner,
    report_type: item.json.report_type,
    expected_time: expectedTime,
    actual_time: item.json.actual_time,
    status: item.json.status,
    size: item.json.size_mb + ' MB',
    alerts_sent: item.json.file_found ? '0' : '2',
    filename: item.json.filename,
    validation: item.json.validation
  }
}];
